#include <array>
#include <cstdint>
#include <format>
#include <string>

std::string describeBugCheck(std::uint32_t code, const std::array<std::uint64_t, 4>& p)
{
    switch (code)
    {
    case 0x0A: return std::format("IRQL_NOT_LESS_OR_EQUAL: address 0x{:X} at IRQL {}", p[0], p[1]);
    case 0xD1: return std::format("DRIVER_IRQL_NOT_LESS_OR_EQUAL: address 0x{:X} at IRQL {}, code at 0x{:X}", p[0], p[1], p[3]);
    case 0x50: return std::format("PAGE_FAULT_IN_NONPAGED_AREA: {} 0x{:X}", p[1] == 0 ? "read" : "write", p[0]);
    case 0xC4: return std::format("DRIVER_VERIFIER_DETECTED_VIOLATION: rule 0x{:X}", p[0]);
    case 0x19: return "BAD_POOL_HEADER";
    default: return std::format("BUGCHECK 0x{:X}", code);
    }
}

unitTests:
TEST("the example") { CHECK_EQ(describeBugCheck(0xD1, { 0x10, 2, 0, 0xFFFFF80612345678ull }), std::string("DRIVER_IRQL_NOT_LESS_OR_EQUAL: address 0x10 at IRQL 2, code at 0xFFFFF80612345678")); }
TEST("0x0A") { CHECK_EQ(describeBugCheck(0x0A, { 0xDEAD, 2, 1, 0 }), std::string("IRQL_NOT_LESS_OR_EQUAL: address 0xDEAD at IRQL 2")); }
TEST("page faults: read and write") { CHECK_EQ(describeBugCheck(0x50, { 0xFFFFA00012340000ull, 0, 0, 0 }), std::string("PAGE_FAULT_IN_NONPAGED_AREA: read 0xFFFFA00012340000")); CHECK_EQ(describeBugCheck(0x50, { 0x8, 2, 0, 0 }), std::string("PAGE_FAULT_IN_NONPAGED_AREA: write 0x8")); }
TEST("verifier") { CHECK_EQ(describeBugCheck(0xC4, { 0x62, 0, 0, 0 }), std::string("DRIVER_VERIFIER_DETECTED_VIOLATION: rule 0x62")); }
TEST("pool") { CHECK_EQ(describeBugCheck(0x19, { 0, 0, 0, 0 }), std::string("BAD_POOL_HEADER")); }
TEST("others") { CHECK_EQ(describeBugCheck(0xEF, { 0, 0, 0, 0 }), std::string("BUGCHECK 0xEF")); }

